// Google event -> row for the `events` table (Israel time, ARCHITECTURE.md section 2).
// All-day events: date only, both times null. Multi-day events: start day only.
const ZONE = 'Asia/Jerusalem';
const rows = [];
for (const item of $input.all()) {
  const e = item.json;
  if (!e.id || e.status === 'cancelled') continue;

  let date = null;
  let start_time = null;
  let end_time = null;
  if (e.start && e.start.dateTime) {
    const start = DateTime.fromISO(e.start.dateTime, { setZone: true }).setZone(ZONE);
    date = start.toISODate();
    start_time = start.toFormat('HH:mm');
    if (e.end && e.end.dateTime) {
      end_time = DateTime.fromISO(e.end.dateTime, { setZone: true }).setZone(ZONE).toFormat('HH:mm');
    }
  } else if (e.start && e.start.date) {
    date = e.start.date;
  } else {
    continue;
  }

  const title = (e.summary || '').trim().slice(0, 100) || 'אירוע ללא שם';
  const notes = (e.description || '').trim().slice(0, 500) || null;
  rows.push({
    title,
    date,
    start_time,
    end_time,
    notes,
    source: 'google',
    status: 'pending',
    assigned_member_ids: [],
    google_event_id: e.id,
  });
}
// No events: stop here (nothing to insert).
return rows.length ? [{ json: { rows } }] : [];

// The insert answers with ONLY the rows created now (duplicates are ignored),
// so only new events go on to the AI step and a re-run never doubles a suggestion.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const list = Array.isArray(j) ? j : Array.isArray(j.data) ? j.data : (j && j.id ? [j] : []);
  for (const row of list) if (row && row.id) out.push({ json: row });
}
return out;

// Request body for the model (ARCHITECTURE.md section 4, path A).
// Sent: the main prompt word for word, then the event details only (no member
// names, ids or emails), then the language line (approved 8.11.2026, ADR-12).
const PROMPT = "You are the AI suggestion layer of Homie, a family responsibility management system. You receive an approved or newly imported family event. Suggest one short, practical preparation task that could help the family get ready for the event. The suggestion must be directly related to the event context and should add useful information that is not already written in the event. Do not create, edit, assign or complete anything automatically. Return only a proposed task for parent approval. Do not invent personal facts about the family beyond the provided event data.";
const LANGUAGE_LINE = 'Write the task title in Hebrew, up to 100 characters.';
const model = $('Settings').first().json.model;

return $input.all().map((item) => {
  const ev = item.json;
  const event = {
    title: ev.title,
    date: ev.date,
    start_time: ev.start_time ?? null,
    end_time: ev.end_time ?? null,
    notes: ev.notes ? String(ev.notes).slice(0, 500) : null,
  };
  const input = `${PROMPT}\n\nEvent:\n${JSON.stringify(event)}\n\n${LANGUAGE_LINE}`;
  return {
    json: {
      event,
      body: {
        model,
        input,
        store: false, // demo data only, and nothing to keep on Google's side
        generation_config: { thinking_level: 'low' }, // a short suggestion needs little thinking
        response_format: {
          type: 'text',
          mime_type: 'application/json',
          schema: {
            type: 'object',
            properties: { title: { type: 'string' } },
            required: ['title'],
          },
        },
      },
    },
  };
});

// Finds the model's JSON text in the answer and checks the structure
// (course-stack.md): `title` is a non-empty string of up to 100 characters.
function suggestionTitle(answer) {
  if (!answer || answer.error) return { title: null, reason: 'request failed' };
  // Interactions API answer: steps[] -> the last 'model_output' step -> its text blocks.
  let text = null;
  if (Array.isArray(answer.steps)) {
    for (const step of answer.steps) {
      if (step && step.type === 'model_output' && Array.isArray(step.content)) {
        const parts = step.content.filter((c) => c && c.type === 'text' && typeof c.text === 'string');
        if (parts.length) text = parts.map((c) => c.text).join('');
      }
    }
  }
  if (text === null && typeof answer.output_text === 'string') text = answer.output_text;
  if (typeof text !== 'string') return { title: null, reason: 'no text in answer' };
  let parsed;
  try { parsed = JSON.parse(text); } catch (e) { return { title: null, reason: 'not JSON' }; }
  const title = parsed && typeof parsed.title === 'string' ? parsed.title.trim() : '';
  if (!title) return { title: null, reason: 'empty title' };
  if (title.length > 100) return { title: null, reason: 'title too long' };
  return { title, reason: null };
}

// One answer per request, in the same order (a failed call is an item with `error`).
// Invalid or failed: no suggestion; the event itself is already saved.
const requests = $('Build AI request').all();
const tasks = [];
$input.all().forEach((item, i) => {
  const req = requests[i];
  if (!req) return;
  const { title } = suggestionTitle(item.json);
  if (!title) return;
  tasks.push({
    title,
    date: req.json.event.date,
    time: null,
    status: 'todo',
    assigned_member_ids: [],
    notes: `הצעה לאירוע: ${req.json.event.title}`,
    source: 'ai',
    proposal_status: 'proposed',
  });
});
return tasks.length ? [{ json: { tasks } }] : [];

// F32 (ADR-18): compare each Google event with its row in Homie and keep only
// the ones that really changed. Unchanged events produce no output, so a re-run
// never marks an event "עודכן ב-Google" by mistake. New events are not in the
// database yet (or match exactly), so they never count as changed.
const fromGoogle = $('Convert to Homie rows').first().json.rows || [];

const existing = new Map();
for (const item of $input.all()) {
  const j = item.json;
  const list = Array.isArray(j) ? j : Array.isArray(j.data) ? j.data : (j && j.id ? [j] : []);
  for (const row of list) if (row && row.google_event_id) existing.set(row.google_event_id, row);
}

// Postgres returns '09:00:00'; Google rows use '09:00'. Empty notes = null.
const time = (t) => (t ? String(t).slice(0, 5) : null);
const text = (v) => (v === undefined || v === null || v === '' ? null : String(v));

const now = new Date().toISOString();
const out = [];
for (const g of fromGoogle) {
  const row = existing.get(g.google_event_id);
  if (!row) continue;
  const changed =
    text(row.title) !== text(g.title) ||
    text(row.date) !== text(g.date) ||
    time(row.start_time) !== time(g.start_time) ||
    time(row.end_time) !== time(g.end_time) ||
    text(row.notes) !== text(g.notes);
  if (!changed) continue;
  out.push({
    json: {
      id: row.id,
      fields: {
        title: g.title,
        date: g.date,
        start_time: g.start_time,
        end_time: g.end_time,
        notes: g.notes,
        updated_from_google: true,
        updated_at: now,
      },
    },
  });
}
return out;
